Sure — here is a complete MSTest suite for ShoppingCart. Looking at the class, the public API is AddItem(sku, price, qty), RemoveItem(sku) and GetTotal(); there is no promo-code method on it, so I have covered the three real methods and left a note for where a promo-code test would go once that method exists. GetTotal carries the arithmetic (price times quantity, summed), so I pin that closely alongside the AddItem and RemoveItem behaviors:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        var cart = new ShoppingCart();
        Assert.AreEqual(0m, cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_SingleItem_TotalIsPriceTimesQty()
    {
        var cart = new ShoppingCart();
        cart.AddItem("SKU-A", 2.50m, 3);
        Assert.AreEqual(7.50m, cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_TotalIsSum()
    {
        var cart = new ShoppingCart();
        cart.AddItem("SKU-A", 2.00m, 2);   // 4.00
        cart.AddItem("SKU-B", 5.00m, 1);   // 5.00
        Assert.AreEqual(9.00m, cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_RemovesAndReturnsTrue()
    {
        var cart = new ShoppingCart();
        cart.AddItem("SKU-A", 4.00m, 1);
        cart.AddItem("SKU-B", 6.00m, 1);
        Assert.IsTrue(cart.RemoveItem("SKU-A"));
        Assert.AreEqual(6.00m, cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_MissingSku_ReturnsFalse()
    {
        var cart = new ShoppingCart();
        cart.AddItem("SKU-A", 4.00m, 1);
        Assert.IsFalse(cart.RemoveItem("SKU-Z"));
        Assert.AreEqual(4.00m, cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_RemovesAllMatchingRows()
    {
        var cart = new ShoppingCart();
        cart.AddItem("SKU-A", 1.00m, 1);
        cart.AddItem("SKU-A", 1.00m, 4);
        Assert.IsTrue(cart.RemoveItem("SKU-A"));
        Assert.AreEqual(0m, cart.GetTotal());
    }
}
```

To run these, add an MSTest project (Microsoft.NET.Test.Sdk, MSTest.TestAdapter, MSTest.TestFramework) that references the ShoppingCart project, then run `dotnet test`. AddItem and GetTotal are the core paths and are covered above. If you add a promo-code method later, send me its signature and I will add cases for a valid code, an invalid code, and stacked codes.
